{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "inLanguage": "hi-IN",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "सौमित्र विहार योजना लखनऊ क्या है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "सौमित्र विहार योजना उत्तर प्रदेश आवास एवं विकास परिषद द्वारा लखनऊ के गोसाईंगंज इलाके में न्यू जेल रोड पर, सिठौली खुर्द (पिन 226501) के पास विकसित की जा रही एक नई आवासीय टाउनशिप है। यह करीब 560 एकड़ में फैली है और कुल मिलाकर 5,000 से ज़्यादा प्लॉट प्रस्तावित हैं। पहले फेज़ में 2,092 आवासीय और 169 कमर्शियल प्लॉट होंगे। यह उत्तर प्रदेश की पहली ऐसी टाउनशिप है जिसमें ज़बरन अधिग्रहण के बजाय किसानों की सहमति से लैंड पूलिंग के ज़रिए ज़मीन ली गई है।"
      }
    },
    {
      "@type": "Question",
      "name": "क्या सौमित्र विहार का रजिस्ट्रेशन शुरू हो गया है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "नहीं, अभी नहीं। 4 सितंबर 2026 तक upavp.in पर न कोई रजिस्ट्रेशन लिंक है, न ब्रोशर, न रेट लिस्ट। योजना पहले 13 जनवरी 2025 को प्रयागराज महाकुंभ में लॉन्च होनी थी लेकिन टल गई। UPAVP ने 11 अगस्त 2026 को रेरा पंजीकरण आवेदन दाखिल किया है, और वह पास होने के बाद सार्वजनिक रजिस्ट्रेशन खोला जाएगा। upavp.in देखते रहिए, और आधिकारिक विंडो खुलने से पहले प्लॉट बुक करने का दावा करने वाले किसी भी व्यक्ति को पैसे मत दीजिए।"
      }
    },
    {
      "@type": "Question",
      "name": "क्या सौमित्र विहार रेरा अप्रूव्ड है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "नहीं। योजना को फ़िलहाल रेरा मंज़ूरी नहीं मिली है। UPAVP ने 11 अगस्त 2026 को यूपी रेरा पोर्टल पर पंजीकरण आवेदन जमा किया है, और यूपी रेरा ने पुष्टि की है कि दस्तावेज़ों का सत्यापन शुरू हो गया है। इसका मतलब है कि आवेदन समीक्षा में है, मंज़ूर नहीं हुआ है। जब ब्रोशर जारी हो, तो उसमें से रेरा नंबर लेकर आवेदन से पहले खुद up-rera.in पर जाँचिए। जो आज आपसे कह रहा है कि यह योजना पहले से रेरा पंजीकृत है, वह गलत जानकारी दे रहा है।"
      }
    },
    {
      "@type": "Question",
      "name": "सौमित्र विहार में प्लॉट साइज़ क्या-क्या हैं?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "फेज़ 1 में छह आवासीय साइज़ हैं: 40.74 वर्ग मीटर (80 प्लॉट), 60.59 वर्ग मीटर (229 प्लॉट), 75 वर्ग मीटर (598 प्लॉट), 122.23 वर्ग मीटर (445 प्लॉट), 200 वर्ग मीटर (579 प्लॉट) और 300 वर्ग मीटर (161 प्लॉट)। इनका जोड़ 2,092 प्लॉट बनता है। कमर्शियल प्लॉट तीन साइज़ में हैं: 100 वर्ग मीटर (107 प्लॉट), 200 वर्ग मीटर (57 प्लॉट) और 1,375 वर्ग मीटर (5 प्लॉट), कुल 169।"
      }
    },
    {
      "@type": "Question",
      "name": "सौमित्र विहार में प्लॉट की कीमत कितनी होगी?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "अनुमानित दर करीब ₹3,000 से ₹3,500 प्रति वर्ग फुट है, जो लगभग ₹32,300 से ₹37,700 प्रति वर्ग मीटर बैठती है। इस आधार पर 75 वर्ग मीटर के प्लॉट की कीमत करीब ₹24.22 से ₹28.26 लाख, और 300 वर्ग मीटर के प्लॉट की करीब ₹96.88 लाख से ₹1.13 करोड़ होगी — रजिस्ट्री और स्टाम्प ड्यूटी से पहले। कृपया याद रखें कि UPAVP ने अभी आधिकारिक रेट लिस्ट जारी नहीं की है, इसलिए इन्हें अनुमान ही मानें। पुरानी रिपोर्ट्स में दर ₹25,000 से ₹26,000 प्रति वर्ग मीटर, यानी करीब ₹2,300 से ₹2,400 प्रति वर्ग फुट बताई गई थी — वह पुराना अनुमान था और अब बढ़ चुका है।"
      }
    },
    {
      "@type": "Question",
      "name": "सौमित्र विहार कौन बना रहा है — UPAVP या LDA?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "UPAVP, यानी उत्तर प्रदेश आवास एवं विकास परिषद, जिसे यूपी हाउसिंग एंड डेवलपमेंट बोर्ड भी कहते हैं। यह लखनऊ विकास प्राधिकरण से अलग संस्था है, जो आईटी सिटी, वेलनेस सिटी, अनंत नगर और वरुण विहार विकसित करता है। दोनों सरकारी संस्थाएँ हैं लेकिन उनकी वेबसाइट और आवेदन प्रक्रिया अलग-अलग हैं। सौमित्र विहार के लिए आपको upavp.in पर आवेदन करना होगा, LDA पोर्टल पर नहीं।"
      }
    },
    {
      "@type": "Question",
      "name": "सौमित्र विहार में कौन आवेदन कर सकता है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "अब तक दो शर्तें सामने आई हैं: आपको उत्तर प्रदेश का निवासी होना चाहिए, और आपकी आयु 18 से 55 वर्ष के बीच होनी चाहिए। UPAVP ने पूरे पात्रता नियम अभी प्रकाशित नहीं किए हैं, और ब्रोशर में आय सीमा, पहले से संपत्ति होने के नियम और आरक्षण श्रेणियों जैसी शर्तें जुड़ सकती हैं। इसलिए कृपया आधिकारिक ब्रोशर आने तक यह न मान लें कि आप पात्र हैं या नहीं।"
      }
    },
    {
      "@type": "Question",
      "name": "यहाँ की लैंड पूलिंग मॉडल में खास क्या है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "सामान्य भूमि अधिग्रहण में सरकार नोटिस जारी करती है और मुआवज़ा तय कर देती है, चाहे किसान सहमत हो या नहीं — जिससे अक्सर मुक़दमे और अटके प्रोजेक्ट बनते हैं। लैंड पूलिंग में किसान अपनी मर्ज़ी से ज़मीन देते हैं और बदले में विकसित प्लॉट पाते हैं। सौमित्र विहार इस तरह बनने वाली उत्तर प्रदेश की पहली टाउनशिप है। ज़मीन पहले ही परिषद के नाम दर्ज हो चुकी है और 192 किसानों को लॉटरी से उनके विकसित प्लॉट मिल चुके हैं। खरीदारों के लिए इसका मतलब है कि आगे ज़मीन विवाद खड़ा होने का जोखिम काफ़ी कम है।"
      }
    },
    {
      "@type": "Question",
      "name": "क्या मैं एजेंट या ब्रोकर के ज़रिए एडवांस में प्लॉट बुक करा सकता हूँ?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "नहीं, और जो कोई यह पेशकश कर रहा है वह आपको ठगने की कोशिश कर रहा है। इस योजना में एडवांस बुकिंग की कोई व्यवस्था है ही नहीं। UPAVP प्लॉट सिर्फ़ आधिकारिक ऑनलाइन रजिस्ट्रेशन विंडो खुलने के बाद कंप्यूटरीकृत लॉटरी से आवंटित करता है। न कोई प्रायोरिटी कोटा है, न कोई स्पेशल बुकिंग, और न ही किसी के पास आपको प्लॉट की गारंटी देने का कोई तरीका। सारा भुगतान सिर्फ़ UPAVP की वेबसाइट से होता है — नक़द कभी नहीं, निजी नंबर पर UPI कभी नहीं, किसी व्यक्ति के नाम चेक कभी नहीं। इकलौती आधिकारिक वेबसाइट upavp.in है।"
      }
    },
    {
      "@type": "Question",
      "name": "सौमित्र विहार में कितने सेक्टर हैं?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "सौमित्र विहार 8 सेक्टरों में नियोजित है। UPAVP ने अभी सेक्टर-वार अंतिम लेआउट जारी नहीं किया है, इसलिए किस सेक्टर में क्या होगा, यह पुष्ट नहीं है। ब्रोशर के साथ आधिकारिक लेआउट आने तक किसी खास सेक्टर में प्लॉट न चुनें और न पैसे दें।"
      }
    },
    {
      "@type": "Question",
      "name": "क्या 2026 में सौमित्र विहार अच्छा निवेश है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "बुनियाद मज़बूत है। यह सरकारी योजना है, ज़मीन सहमति आधारित पूलिंग से आई है इसलिए विवाद का जोखिम कम है, रजिस्ट्री पहले ही हो चुकी है, और 560 एकड़ का बड़ा प्रोजेक्ट है। दूसरी तरफ़, रेरा मंज़ूरी अभी बाकी है, रजिस्ट्रेशन खुला नहीं है, आधिकारिक रेट लिस्ट नहीं है, अनुमानित दर एक बार बढ़कर ₹3,000 से ₹3,500 प्रति वर्ग फुट हो चुकी है, और साइट पर विकास कार्य शुरू नहीं हुआ है। इसे 3 से 5 साल का निवेश मानिए। रजिस्ट्रेशन खुलने पर आधिकारिक लॉटरी से आवेदन करें, सिर्फ़ आधिकारिक दर चुकाएँ, और ब्रोशर आने से पहले किसी को पैसे न दें।"
      }
    },
    {
      "@type": "Question",
      "name": "सौमित्र विहार ठीक कहाँ स्थित है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "साइट लखनऊ के मोहनलालगंज के पास गोसाईंगंज इलाके में न्यू जेल रोड पर है, सिठौली खुर्द (पिन 226501) के आसपास। निर्देशांक लगभग 26.7244 डिग्री उत्तर और 81.0690 डिग्री पूर्व हैं। टाउनशिप की ज़मीन इसी बेल्ट के गाँवों से आई है, जिनमें मोहारी कला, सिठौली कला और सिठौली खुर्द शामिल हैं। कृपया ध्यान रखें कि यह अभी खुली ज़मीन है, ज़्यादातर खेत, और आसपास सुविधाएँ सीमित हैं।"
      }
    }
  ]
}
